// Confere o pedido do autor: tema, público, tamanho, autor, oferta do final (opcional) e a captura. Cria o código do e-book e a chave do painel.
const crypto = require('crypto');
const req = $('🔔 Pedido do e-book (POST)').first().json;
let b = req.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const base = String(req.webhookUrl || '').split('/webhook/')[0];
const erros = [];
const tema = ebL(b.tema, 120);
if (tema.length < 4) erros.push('Diga o tema do e-book.');
const autor = { nome: ebL(b.autor, 60), bio: ebL(b.bio, 300) };
if (autor.nome.length < 2) erros.push('Diga o nome do autor ou da marca.');
const TONS = { amigavel: 'amigável e direto', profissional: 'profissional', inspirador: 'inspirador' };
const tom = TONS[b.tom] ? b.tom : 'amigavel';
const capitulos = Math.max(4, Math.min(8, parseInt(b.capitulos, 10) || 5));
let zap = String(b.whatsapp || '').replace(/\D/g, '');
if (zap.length === 10 || zap.length === 11) zap = '55' + zap;
if (zap.length < 12 || zap.length > 13) zap = '';
const link = /^https:\/\/[^\s"'<>]{6,300}$/.test(String(b.link || '').trim()) ? String(b.link).trim() : '';
const oferta = { produto: ebL(b.oferta, 120), preco: ebNum(b.preco), whatsapp: zap, link };
const op = { imagens: b.imagens !== false, pedir_email: b.pedir_email === true, crm: b.crm !== false, cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : '#B23A48' };
const dados = { tema, publico: ebL(b.publico, 200), objetivo: ebL(b.objetivo, 300), tom, autor, capitulos, oferta, observacoes: ebL(b.observacoes, 800) };
const slug = tema.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 30).replace(/-+$/, '') || 'ebook';
const id = `${slug}-${crypto.randomBytes(2).toString('hex')}`;
const chave = crypto.randomBytes(16).toString('hex');
const resumo_ia = `TEMA: ${tema}
PÚBLICO: ${dados.publico || '(não informado)'}
O QUE O LEITOR DEVE APRENDER: ${dados.objetivo || '(deduza algo concreto e honesto)'}
TAMANHO: ${capitulos} capítulos (o e-book todo com 15 a 30 páginas A4)
TOM: ${TONS[tom]}
AUTOR: ${autor.nome}${autor.bio ? ' — ' + autor.bio : ''}
OFERTA DO AUTOR NO FINAL: ${oferta.produto ? oferta.produto + (oferta.preco ? ' — ' + 'R$ ' + oferta.preco.toFixed(2).replace('.', ',') : '') : '(nenhuma)'}
OBSERVAÇÕES: ${dados.observacoes || '(nenhuma)'}`;
return [{ json: {
  valido: erros.length === 0, erros, id, chave, criado_em: Date.now(), dados, op, resumo_ia,
  link: `${base}/webhook/ebook/${id}/baixar`, painel: `${base}/webhook/ebook-painel?id=${id}&chave=${chave}`, chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13),
} }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

