// Aplica a revisão editorial de cada capítulo (se o revisor falhar, fica o do escritor) e a TRAVA: promessa de ganho/resultado e R$ que não é o preço da oferta saem.
// Junta tudo num item só e prepara o redator da captura e os pedidos das imagens (capa + 1 por capítulo).
const V = $('🧩 Confere o pedido').first().json, plano = $('🧩 Lê o sumário').first().json.plano;
const escritos = $('🧩 Lê os capítulos').all().map(i => i.json), res = $input.all().map(i => i.json);
const valores = new Set(V.dados.oferta.preco ? [Math.round(V.dados.oferta.preco * 100)] : []);
const problemas = [], trava = [];
const capitulos = escritos.map((E, i) => {
  let r = null;
  try { r = parseJSON((res[i] || {}).output); } catch (e) {}
  if (r && Array.isArray(r.problemas)) r.problemas.map(p => ebT(p, 200)).filter(p => p && !/\bok\b|está corret|estão corret|nenhum problema|sem altera/i.test(p)).slice(0, 3).forEach(p => problemas.push(`Capítulo ${E.n}: ${p}`));
  let c = r && (r.secoes || r.abertura) ? ebCapitulo(r, { n: E.cap.n, titulo: ebL(r.titulo, 80) || E.cap.titulo, objetivo: E.cap.objetivo }) : E.cap;
  if (!c.imagem_prompt) c.imagem_prompt = E.cap.imagem_prompt;
  const G = (t, onde) => ebGuarda(t, valores, `Capítulo ${c.n} (${onde})`, trava);
  c = { ...c, abertura: G(c.abertura, 'abertura'), secoes: c.secoes.map(s => ({ ...s, paragrafos: s.paragrafos.map(p => G(p, s.titulo || 'texto')).filter(Boolean), lista: s.lista.map(l => G(l, 'lista')).filter(Boolean) })),
    dica: G(c.dica, 'dica'), exemplo: G(c.exemplo, 'exemplo'), destaque: G(c.destaque, 'destaque') };
  return { ...c, palavras: ebPalavras(c), revisou: !!r };
});
const palavras = capitulos.reduce((s, c) => s + c.palavras, 0);
const o = V.dados.oferta;
const texto_captura = `${V.resumo_ia}
E-BOOK: ${plano.titulo} — ${plano.subtitulo}
PROMESSA (fiel): ${plano.promessa}
CAPÍTULOS: ${capitulos.map(c => `${c.n}. ${c.titulo}`).join(' · ')}
TAMANHO: ~${Math.max(12, Math.round(palavras / 380) + 3)} páginas
OFERTA DO AUTOR: ${o.produto ? `${o.produto}${o.preco ? ' por R$ ' + o.preco.toFixed(2).replace('.', ',') : ''} (contato: ${o.whatsapp ? 'WhatsApp' : o.link ? 'link' : 'nenhum'})` : '(nenhuma: a sequência termina convidando para falar com o autor)'}`;
const FIM = ' Clean modern editorial illustration, soft light, harmonious colors, high quality. No text, no letters, no numbers, no logos, no people faces.';
const pedidos = !V.op.imagens ? [] : [{ nome: 'img-01', uso: 'capa', prompt: `Book cover background about ${V.dados.tema}: elegant, calm and inspiring scene, vertical composition with empty dark area at the bottom for the title.` + FIM },
  ...capitulos.map(c => ({ nome: 'img-' + String(c.n + 1).padStart(2, '0'), uso: 'capítulo ' + c.n, prompt: (c.imagem_prompt || `Illustration about: ${c.titulo}`) + '.' + FIM }))];
return [{ json: { capitulos, problemas, trava, palavras, texto_captura, pedidos, imagens: pedidos.length > 0 } }];

