function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Regras do e-book (as mesmas na criação, no PDF, na leitura online e no painel).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const ebT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const ebL = (v, max) => ebT(v, max).replace(/[<>{}]/g, '');
const ebEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const ebNum = v => {
  if (typeof v === 'number') return isFinite(v) && v >= 0 ? Math.round(v * 100) / 100 : null;
  let s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) && n >= 0 ? Math.round(n * 100) / 100 : null;
};
const ebHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const ebLum = h => ebHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const ebContraste = (a, b) => { const x = ebLum(a), y = ebLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const ebMistura = (a, b, k) => { const x = ebHex(a), y = ebHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
function ebTokens(cor) {
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : '#B23A48';
  let forte = c;
  for (let i = 0; i < 16 && ebContraste(forte, '#FFFFFF') < 4.5; i++) forte = ebMistura(forte, '#000000', 0.12);
  return { cor: c, forte, tinta: ebContraste('#FFFFFF', forte) >= 4.5 ? '#FFFFFF' : '#111111', suave: ebMistura(c, '#FFFFFF', 0.9), linha: ebMistura(c, '#FFFFFF', 0.72), escuro: ebMistura(forte, '#000000', 0.5) };
}
// trava: promessa de ganho/resultado garantido e R$ que não é o preço da oferta do autor saem da frase
const EB_PROMESSA = /(ganh\w*|fatur\w*|lucr\w*|renda)\s+(de\s+)?(at[eé]\s+)?r\$|fique\s+rico|ficar\s+rico|dinheiro\s+f[aá]cil|resultado\s+garantid|garantimos\s+(que|o\s+seu)|100%\s+garantid|sem\s+esfor[cç]o|cura\s+(garantid|definitiv)|emagre[cç]a\s+\d+/i;
function ebGuarda(txt, valores, onde, problemas) {
  return String(txt || '').split(/(?<=[.!?…])\s+/).filter(f => {
    const vs = (f.match(/R\$\s?\d[\d.]*(?:,\d{1,2})?/g) || []).map(x => Math.round(ebNum(x) * 100)).filter(n => !valores.has(n));
    const prom = EB_PROMESSA.test(f);
    if ((vs.length || prom) && problemas) problemas.push(`${onde}: tirei "${ebT(f, 90)}" (${prom ? 'promessa de ganho/resultado' : 'valor que não é o seu'})`);
    return !vs.length && !prom;
  }).join(' ').trim();
}
// capítulo do escritor (ou do revisor) no formato do livro
function ebCapitulo(x, base) {
  x = x && typeof x === 'object' ? x : {};
  const lista = v => (Array.isArray(v) ? v : []).map(i => ebL(i, 220)).filter(Boolean);
  const secoes = (Array.isArray(x.secoes) ? x.secoes : []).filter(s => s && typeof s === 'object').map(s => ({ titulo: ebL(s.titulo, 90),
    paragrafos: (Array.isArray(s.paragrafos) ? s.paragrafos : [s.texto]).map(p => ebL(p, 1400)).filter(Boolean).slice(0, 5), lista: lista(s.lista).slice(0, 8) }))
    .filter(s => s.paragrafos.length || s.lista.length).slice(0, 5);
  return { ...base, abertura: ebL(x.abertura, 900), secoes, dica: ebL(x.dica, 500), exemplo: ebL(x.exemplo, 900), destaque: ebL(x.destaque, 200), resumo: lista(x.resumo).slice(0, 5),
    imagem_prompt: ebT(x.imagem, 500), imagem: '' };
}
const ebPalavras = cap => [cap.abertura, ...cap.secoes.flatMap(s => [...s.paragrafos, ...s.lista]), cap.dica, cap.exemplo, ...cap.resumo].join(' ').split(/\s+/).filter(Boolean).length;
// o livro em A4 para o PDF (o Chromium imprime): capa, sumário, capítulos com ilustração, página final com o autor e a oferta
function ebLivroHtml(eb, ARQ) {
  const t = eb.cores, E = ebEsc, img = f => f ? `${ARQ}${f}` : '';
  const capitulo = (c, i) => `<section class="cap"><div class="num">Capítulo ${i + 1}</div><h1>${E(c.titulo)}</h1>${c.imagem ? `<img class="ilu" src="${img(c.imagem)}">` : ''}
<p class="ab">${E(c.abertura)}</p>${c.secoes.map(s => `${s.titulo ? `<h2>${E(s.titulo)}</h2>` : ''}${s.paragrafos.map(p => `<p>${E(p)}</p>`).join('')}${s.lista.length ? `<ul>${s.lista.map(l => `<li>${E(l)}</li>`).join('')}</ul>` : ''}`).join('')}
${c.destaque ? `<blockquote>${E(c.destaque)}</blockquote>` : ''}${c.exemplo ? `<div class="box ex"><b>Exemplo prático</b><p>${E(c.exemplo)}</p></div>` : ''}${c.dica ? `<div class="box"><b>💡 Dica</b><p>${E(c.dica)}</p></div>` : ''}
${c.resumo.length ? `<div class="res"><b>Para lembrar</b><ul>${c.resumo.map(r => `<li>${E(r)}</li>`).join('')}</ul></div>` : ''}</section>`;
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${E(eb.titulo)}</title><style>
