// Lê a página de captura e a sequência de 3 mensagens (vale a revisada; se o revisor falhar, a do redator; sem nenhuma, textos padrão).
// Trava: promessa de ganho/resultado e R$ fora do preço da oferta saem; {nome} e {link} precisam estar nas mensagens.
const V = $('🧩 Confere o pedido').first().json, plano = $('🧩 Lê o sumário').first().json.plano, R = $('🧩 Aplica a revisão').first().json;
let a = null, rv = null;
try { a = parseJSON($('🤖 Redator da captura').first().json.output); } catch (e) {}
try { rv = parseJSON($('🤖 Revisor da captura').first().json.output); } catch (e) {}
const x = rv && rv.titulo ? rv : a && a.titulo ? a : {};
const valores = new Set(V.dados.oferta.preco ? [Math.round(V.dados.oferta.preco * 100)] : []);
const trava = [];
const G = (t, n, onde) => ebGuarda(ebL(t, n), valores, 'captura (' + onde + ')', trava);
const o = V.dados.oferta;
const padrao = [
  `Oi, {nome}! Aqui está o seu e-book "${plano.titulo}": {link} 📘 Começa pelo capítulo 1, ele é rapidinho.`,
  `{nome}, conseguiu ler o e-book? O capítulo 2 tem a parte mais prática. Se travar em algo, me responde aqui que eu te ajudo.`,
  o.produto ? `{nome}, quem leu o e-book costuma querer ir além. Eu tenho ${o.produto}. Quer saber como funciona?` : `{nome}, o que achou do e-book? Me conta o que foi mais útil pra você.`,
];
const msgs = (Array.isArray(x.mensagens) ? x.mensagens : []).filter(m => m && typeof m === 'object');
// a IA escreve [NOME] e [LINK]; aqui viram {nome} e {link} (trocados por lead na hora de guardar)
const marca = t => String(t || '').replace(/\[\s*nome\s*\]|\{+\s*nome\s*\}+/gi, '{nome}').replace(/\[\s*link\s*\]|\{+\s*link\s*\}+/gi, '{link}');
const mensagens = [0, 2, 5].map((dia, i) => {
  let t = marca(G((msgs.find(m => Number(m.dia) === dia) || msgs[i] || {}).texto, 600, `mensagem do dia ${dia}`)) || padrao[i];
  if (/(envi|mand)\w*[^.!?]{0,60}e-?mail|no seu e-?mail|caixa de entrada|spam/i.test(t)) { trava.push(`mensagem do dia ${dia}: dizia que o e-book foi por e-mail (ele é entregue na página): voltou o texto padrão`); t = padrao[i]; }
  if (!t.includes('{nome}')) t = '{nome}, ' + t.charAt(0).toLowerCase() + t.slice(1);
  if (i === 0 && !t.includes('{link}')) t += ' {link}';
  return { dia, texto: t };
});
const captura = {
  titulo: G(x.titulo, 90, 'título') || plano.titulo, subtitulo: G(x.subtitulo, 200, 'subtítulo') || plano.subtitulo,
  bullets: (Array.isArray(x.bullets) ? x.bullets : []).map(b => G(b, 140, 'bullets')).filter(Boolean).slice(0, 6),
  cta: ebL(x.cta, 34) || 'Quero o e-book grátis', privacidade: ebL(x.privacidade, 160) || 'Seus dados ficam só com ' + V.dados.autor.nome + '. Nada de spam.',
  entrega: { titulo: ebL(x.entrega && x.entrega.titulo, 70) || 'Pronto! Seu e-book chegou 🎉', texto: G(x.entrega && x.entrega.texto, 240, 'entrega') || 'Leia agora aqui mesmo ou baixe o PDF.' },
  faq: (Array.isArray(x.faq) ? x.faq : []).filter(f => f && typeof f === 'object').map(f => ({ p: ebL(f.p, 140), r: G(f.r, 400, 'dúvidas') })).filter(f => f.p && f.r).slice(0, 5),
  oferta: o.produto ? { titulo: G(x.oferta && x.oferta.titulo, 80, 'oferta') || o.produto, texto: G(x.oferta && x.oferta.texto, 260, 'oferta'), botao: ebL(x.oferta && x.oferta.botao, 30) || 'Quero saber mais',
    link: o.link || (o.whatsapp ? `https://wa.me/${o.whatsapp}?text=${encodeURIComponent('Olá! Li o e-book "' + plano.titulo + '" e quero saber mais sobre ' + o.produto + '.')}` : '') } : null,
};
if (captura.bullets.length < 3) captura.bullets = R.capitulos.map(c => c.titulo).slice(0, 6);
const problemas = rv && Array.isArray(rv.problemas) ? rv.problemas.map(p => ebT(p, 200)).filter(p => p && !/\bok\b|está corret|estão corret|nenhum problema|sem altera/i.test(p)).slice(0, 4) : [];
return [{ json: { captura, mensagens, problemas, trava } }];

