const guardadas = Array.isArray(g.imagens) ? g.imagens : [];
const conteudo = [{ type: 'text', text: `Você revisa imagens geradas por IA para um e-book sobre "${V.dados.tema}" (fundo da capa e ilustração de abertura de cada capítulo).
