if (!eb) return pagina(404, 'E-book não encontrado', 'Confira o link.');
const autor = (q.query || {}).chave === eb.chave;
if (!l && !autor) return pagina(403, 'Pegue o seu e-book', `Para ler, deixe seu contato na <a href="${base}/webhook/ebook/${eb.id}/baixar">página do e-book</a>.`);
