  var manda = function (corpo) { if (!D.lead) return; try { navigator.sendBeacon('/webhook/ebook-ler', new Blob([JSON.stringify(corpo)], { type: 'text/plain' })); } catch (e) {} };
  var vistos = {};
  var obs = new IntersectionObserver(function (es) {
    es.forEach(function (e) { if (e.isIntersecting) { var n = Number(e.target.dataset.n); if (!vistos[n]) { vistos[n] = 1; manda({ id: D.id, lead: D.lead, acao: 'capitulo', n: n }); } } });
  }, { rootMargin: '0px 0px -60% 0px' });
  document.querySelectorAll('.cap .fimcap').forEach(function (f) { obs.observe(f); });
  window.addEventListener('scroll', function () { var h = document.documentElement; el('#barra i').style.width = Math.min(100, Math.round(h.scrollTop / Math.max(1, h.scrollHeight - h.clientHeight) * 100)) + '%'; }, { passive: true });
