let b = $('🔔 Lead do e-book (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const WH = $('🔔 Lead do e-book (POST)').first().json, h = WH.headers || {};
const ip = String(h['x-real-ip'] || String(h['x-forwarded-for'] || 'sem-ip').split(',')[0]).trim().replace(/[^0-9a-fA-F.:]/g, '').slice(0, 45) || 'sem-ip';
