</style></head><body><div class="w">
<div class="card"><h1>📘 ${E(eb.titulo)}</h1><p class="sub">${eb.capitulos.length} capítulos${eb.paginas ? ' · ' + eb.paginas + ' páginas' : ''} · ${E(eb.autor.nome)}</p>
<div class="duas" style="margin-top:8px"><div><b>Página de captura</b> (divulgue)<code>${E(links.captura)}</code><div class="bts"><a class="btn sec" href="${E(links.captura)}?p=1" target="_blank" rel="noopener">👁️ Ver (prévia)</a><button class="btn sec" type="button" data-copiar="${E(links.captura)}">📋 Copiar</button></div></div>
<div><b>O e-book</b><div class="bts"><a class="btn sec" href="${E(links.ler)}" target="_blank" rel="noopener">📖 Ler online</a>${links.pdf ? `<a class="btn sec" href="${E(links.pdf)}" target="_blank" rel="noopener">⬇️ PDF</a>` : ''}</div></div></div></div>
<div class="kpis"><div class="kpi"><small>Visitas na captura</small><b>${N.visitas}</b><span>pessoas diferentes</span></div><div class="kpi"><small>Leads</small><b>${N.leads}</b><span>conversão ${String(N.conversao).replace('.', ',')}%</span></div>
<div class="kpi"><small>Quentes (nota 70+)</small><b>${N.quentes}</b><span>pela IA qualificadora</span></div><div class="kpi"><small>Baixaram o PDF</small><b>${N.pdf}</b><span>leads</span></div><div class="kpi"><small>Leram tudo</small><b>${N.leram_tudo}</b><span>todos os capítulos</span></div></div>
<div class="card"><h2>📖 Até onde leram</h2><div class="barras">${leitura.map(c => `<div class="barra"><span>${c.n}. ${E(c.titulo)}</span><div class="b" aria-hidden="true"><i style="width:${c.pct}%"></i></div><span>${c.leram} (${c.pct}%)</span></div>`).join('')}</div></div>
<div class="card"><h2>👥 Leads</h2><p class="sub">As 3 mensagens (dia 0, 2 e 5) já vêm com o nome e o link de cada um: toque para abrir no WhatsApp.</p>
<div class="filtros" style="margin-top:8px"><input type="search" id="filtro" placeholder="Filtrar por nome, desafio, temperatura…" aria-label="Filtrar leads"><button class="btn sec" id="csv" type="button">⬇️ CSV</button></div>
<div class="rol"><table id="t"><thead></thead><tbody></tbody></table></div></div>
${(eb.revisao.problemas || []).length || (eb.revisao.trava || []).length ? `<div class="card"><h2>🔍 O que a revisão ajustou</h2><ul class="lista">${[...(eb.revisao.problemas || []), ...(eb.revisao.trava || [])].slice(0, 12).map(p => `<li>${E(p)}</li>`).join('')}</ul></div>` : ''}
</div><script>(${app.toString()})(${JSON.stringify(dados).replace(/</g, '\\u003c')});</script></body></html>`;
return [{ json: { codigo: 200, tipo: 'text/html; charset=UTF-8', html } }];

// a criação responde na hora; as IAs continuam em segundo plano
const r = $input.first().json;
if (!r.ok) throw new Error('A criação recusou o teste: ' + (r.erros || [r.message || 'sem resposta']).join(' '));
return [{ json: { id: r.id, link: r.link, painel: r.painel, json: r.painel + '&json=1' } }];

// Confere cada passo do teste; se algo não bateu, o node fica vermelho dizendo o quê.
const l = $('👉 Guarda os links').first().json, st = $('🚦 Ficou pronto?').first().json;
const j = x => { if (typeof x.data === 'string') { try { return JSON.parse(x.data); } catch (e) { return { texto: x.data }; } } return x; };
const l1 = j($('🌐 Carla pega o e-book').first().json), l2 = j($('🌐 Diego pega o e-book').first().json), l3 = j($('🌐 Lead sem contato').first().json);
const ler = String($('🌐 Carla abre a leitura').first().json.data || ''), semLead = String($('🌐 Leitura sem cadastro').first().json.data || '');
const pdf = $('🌐 Abre o PDF').first().json, cap = String($('🌐 Abre a captura').first().json.data || ''), p = j($('🌐 Painel em dados').first().json), errada = String($('🌐 Painel com chave errada').first().json.data || '');
const falhas = [], ok = (c, m) => { if (!c) falhas.push(m); };
ok(st.etapa === 'pronto' && st.capitulos === 4 && st.paginas >= 8 && st.pdf, 'O e-book não ficou pronto com 4 capítulos e o PDF: ' + JSON.stringify(st).slice(0, 300));
ok(l1.ok && /\/ler\?l=[A-Z0-9]{10}$/.test(l1.ler || '') && /ebook\.pdf$/.test(l1.pdf || ''), 'A Carla devia receber o link de leitura e o PDF: ' + JSON.stringify(l1));
ok(l2.ok, 'O Diego (só e-mail) devia receber o e-book: ' + JSON.stringify(l2));
ok(!l3.ok && /WhatsApp|e-mail/.test(l3.erro || ''), 'Lead sem contato devia ser recusado: ' + JSON.stringify(l3));
ok(ler.includes('Capítulo 1') && ler.includes('Sumário') && ler.includes('ebook-ler'), 'A leitura da Carla não abriu com os capítulos');
ok(semLead.includes('Pegue o seu e-book'), 'A leitura sem cadastro devia mandar para a captura');
ok(Number(pdf.statusCode) === 200 && /application\/pdf/.test(JSON.stringify(pdf.headers || {})), 'O PDF não abriu: ' + pdf.statusCode);
ok(cap.includes('E-book grátis') && cap.includes('ebook-lead'), 'A página de captura não veio certa');
const N = p.numeros || {}, carla = (p.leads || []).find(x => x.nome === 'Carla Teste') || {};
ok(N.visitas === 2 && N.leads === 2 && N.pdf === 1, 'Números do painel errados (esperado 2 visitas, 2 leads, 1 PDF): ' + JSON.stringify(N));
ok((p.leitura || [])[0] && p.leitura[0].leram === 1 && p.leitura[1].leram === 1 && p.leitura[2].leram === 0, 'Leitura por capítulo errada (Carla leu 1 e 2): ' + JSON.stringify(p.leitura));
ok(isFinite(carla.nota) && carla.temperatura && carla.caps === 2 && carla.pdf, 'A Carla devia ter nota, 2 capítulos lidos e o PDF: ' + JSON.stringify(carla).slice(0, 300));
ok((carla.mensagens || []).length === 3 && carla.mensagens.every(m => !m.texto.includes('{nome}') && !m.texto.includes('{link}')) && carla.mensagens[0].texto.includes('/ler?l='),
  'As 3 mensagens da Carla deviam vir com o nome e o link: ' + JSON.stringify(carla.mensagens).slice(0, 300));
ok(errada.includes('Chave errada'), 'Painel com chave errada devia recusar');
// a nota da IA não pode se perder quando o leitor começa a ler na hora (leitura e nota ficam em chaves separadas)
ok(carla.resumo && !/^Baixou o e-book/.test(carla.resumo), 'A nota da IA da Carla se perdeu (ficou a da regra): ' + carla.resumo);
const d0 = ((carla.mensagens || [])[0] || {}).texto || '';
ok(d0.includes('Carla') && !/\bnome\b/i.test(d0) && !/e-?mail|spam/i.test(d0), 'A mensagem do dia 0 devia ter o nome da Carla e não falar de e-mail: ' + d0);
if (falhas.length) throw new Error(falhas.join(' | '));
return [{ json: { '✅': `E-book pronto em ${st.segundos} s (4 capítulos, ${st.paginas} páginas, ${st.imagens} imagens da IA, PDF); 2 leads (WhatsApp e só e-mail), sem contato recusado; leitura marcou os capítulos 1 e 2 e o PDF; painel com visitas, conversão e as 3 mensagens prontas`,
  '📘 captura': l.link, '📊 painel': l.painel, '📄 PDF': st.pdf, '🔥 Carla': `${carla.nota} (${carla.temperatura}) — ${carla.resumo}`, '💬 dia 0': (carla.mensagens || [{}])[0].texto } }];
